import {PRIORITIES,openItem} from './domain.js';
import {PlanningPreferences,PLANNING_KEY,dueReminders,postpone,reminderDate,calendarTemplate,validZone} from './planning.js';
import {checkForm,submitOnce} from './forms.js';
export function createPlanningUI({storage,getState,icon,esc,openModal,closeModal,toast,onOpen,onEdit,onComplete,target=window,now=()=>new Date(),appUrl=new URL('./',target.location.href).href}){
  const preferences=new PlanningPreferences(storage);let visible=60,timer;
  const prefs=()=>preferences.value;
  const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
  const check=(id,label,checked)=>`<label class="planning-check" for="${id}"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`;
  const items=()=>dueReminders(getState(),prefs(),now());
  function header(){const list=items();return `<button type="button" class="reminder-trigger" data-action="planning-open" aria-label="Lembretes: ${list.length} ${list.length===1?'prazo próximo ou atrasado':'prazos próximos ou atrasados'}" title="Lembretes">${icon('bell')}${list.length?`<span class="reminder-count" aria-hidden="true">${list.length>99?'99+':list.length}</span>`:''}</button>`}
  function summaryContent(){const list=items();if(!list.length)return '';const late=list.filter(x=>x.overdue).length,today=list.filter(x=>x.group==='today').length;return `<button class="reminder-summary" data-action="planning-open">${icon('bell')}<span><strong>${list.length} ${list.length===1?'prazo para acompanhar':'prazos para acompanhar'}</strong><small>${[late?late+' em atraso':'',today?today+' para hoje':'',list.length-late-today?list.length-late-today+' '+(list.length-late-today===1?'próximo':'próximos'):''].filter(Boolean).join(' · ')}</small></span>${icon('right')}</button>`}
  const summary=()=>`<div id="planning-summary">${summaryContent()}</div>`;
  function calendarButton(t,text=false){
    const className=text?'textbtn':'calendar-action priority-'+t.priority,content=icon('calendar-plus')+(text?' Google Agenda':'');
    if(t.date)try{return `<a class="${className}" href="${esc(calendarTemplate(getState(),t.id,prefs().calendar,appUrl))}" target="_blank" rel="noopener noreferrer" data-action="planning-calendar-web" data-id="${esc(t.id)}" aria-label="Abrir evento no Google Agenda: ${esc(t.title)}" title="Abrir no Google Agenda e salvar">${content}</a>`}catch{}
    return `<button type="button" class="${className}" data-action="planning-calendar" data-id="${esc(t.id)}" aria-label="${t.date?'Abrir evento no Google Agenda: ':'Definir data para enviar ao Google Agenda: '}${esc(t.title)}" title="${t.date?'Google Agenda':'Defina uma data para enviar ao Google Agenda'}">${content}</button>`;
  }
  function reminderRows(){const list=items(),show=list.slice(0,visible),state=getState();if(!prefs().reminders.enabled)return `<div class="empty"><h2>Lembretes desativados</h2><p>Ative os avisos para acompanhar os prazos dos seus itens e subitens.</p><button class="btn primary" data-action="planning-reminder-settings">Configurar lembretes</button></div>`;
    if(!list.length)return `<div class="empty"><span class="emptyicon">${icon('bell')}</span><h2>Nenhum prazo para lembrar agora</h2><p>Itens e subitens em aberto aparecem aqui de acordo com suas próprias datas. Concluídos, cancelados e itens sem data ficam fora dos avisos.</p><button class="btn secondary" data-action="planning-reminder-settings">Ajustar lembretes</button></div>`;
    return `<div class="reminder-list">${show.map(entry=>{const t=entry.item,p=PRIORITIES.find(x=>x.id===t.priority),parent=t.parentId?state.items[t.parentId]:null;return `<article class="reminder-card priority-${t.priority}"><div class="reminder-card-head"><span class="reminder-date ${entry.overdue?'late':''}">${icon('clock')}${esc(reminderDate(entry,now(),prefs().calendar.timeZone))}</span><span class="reminder-priority">${p.symbol} ${p.label}</span></div><button class="reminder-title" data-action="planning-edit" data-id="${esc(t.id)}">${esc(t.title)}</button><p class="reminder-context">${t.parentId?'Subitem':'Item'} · ${esc(state.areas[t.areaId]?.name)}${parent?'<br>Em: '+esc(parent.title):''}</p><div class="reminder-actions"><button class="textbtn" data-action="planning-complete" data-id="${esc(t.id)}">${icon('check')} Concluir</button>${calendarButton(t,true)}<button class="textbtn" data-action="planning-snooze" data-id="${esc(t.id)}">${icon('clock')} Adiar ${prefs().reminders.snoozeMinutes<60?prefs().reminders.snoozeMinutes+' min':prefs().reminders.snoozeMinutes/60+' h'}</button><button class="textbtn" data-action="planning-dismiss" data-id="${esc(t.id)}">Dispensar hoje</button></div></article>`}).join('')}</div>${list.length>visible?`<div class="collection-more"><p>${visible} de ${list.length} lembretes</p><button class="btn secondary" data-action="planning-more">Mostrar mais 60</button></div>`:''}`;
  }
  function page(){return `<div class="page-heading"><div><h1>Lembretes</h1><p>Datas primeiro, com o horário e a prioridade de cada etapa.</p></div></div><div class="reminder-toolbar"><button class="textbtn" data-action="page" data-page="plan">${icon('left')} Planejamento</button><button class="textbtn" data-action="planning-reminder-settings">${icon('settings')} Configurar</button></div><div id="reminders-results">${reminderRows()}</div>`}
  function notificationGuide(){return `<p>Os eventos usam as notificações padrão da agenda escolhida. Para definir um aviso específico ao adicionar:</p><ol class="calendar-steps"><li>Na tela do evento no Google Agenda, procure <strong>Notificação</strong> ou <strong>Adicionar notificação</strong>. Se necessário, abra Mais opções.</li><li>Escolha com quanto tempo de antecedência deseja receber o aviso.</li><li>Confira os dados e toque em <strong>Salvar</strong>.</li></ol><p class="field-help">A escolha do aviso é feita no Google. O link de adição do Retomar não configura a antecedência automaticamente. No celular, o Google Agenda precisa ter permissão para enviar notificações.</p>`}
  function notificationHelp(){openModal('Notificações no Google Agenda',notificationGuide()+`<p class="field-help">Para usar o mesmo aviso em novos eventos, ajuste as notificações padrão nas configurações da agenda no Google. Essa preferência é gerenciada pelo Google Agenda.</p>`)}
  function settings(){const r=prefs().reminders,c=prefs().calendar;return `${preferences.error?`<p class="planning-warning" role="status">${esc(preferences.error)}</p>`:''}<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('bell')}</span><div><h2>Lembretes de tarefas</h2><p>${r.enabled?(r.aheadDays===1?'Hoje e amanhã':'Hoje'+(r.aheadDays?' e os próximos '+r.aheadDays+' dias':''))+(r.overdue?', incluindo atrasados.':'.'):'Avisos desativados neste aparelho.'}</p></div></div><p>Os avisos aparecem ao abrir e usar o Retomar. Itens e subitens usam seus próprios prazos.</p><button class="btn secondary" data-action="planning-reminder-settings">Configurar lembretes ${icon('arrow')}</button></section><section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('calendar-plus')}</span><div><h2>Google Agenda</h2><p>Adicionar sem configuração</p></div></div><p>Toque no calendário de um item ou subitem. O evento abre preenchido no Google para você conferir e salvar.</p><ol class="calendar-steps"><li>Confira a conta, a agenda de destino e os dados do evento.</li><li>Escolha a cor e a <strong>notificação</strong> no Google Agenda.</li><li>Toque em <strong>Salvar</strong> para adicionar.</li></ol><p class="field-help">${c.duration} min para eventos com horário · ${c.undatedTime==='allDay'?'Sem horário: dia inteiro':'Sem horário: '+esc(c.defaultTime)}<br>Fuso: ${esc(c.timeZone)}</p><div class="settings-buttons calendar-settings-buttons"><button class="btn secondary" data-action="planning-calendar-settings">Ajustar eventos ${icon('arrow')}</button><button class="btn secondary" data-action="planning-calendar-notifications">${icon('bell')} Como definir notificações</button></div><details class="settings-details"><summary>O evento não apareceu na agenda?</summary><p>Abrir o evento não o salva automaticamente. No Google, confira a conta e a agenda escolhidas e toque em Salvar. Se a tela não abrir, use Não abriu? no aviso que aparece ao tocar no calendário. Essa opção permite abrir nesta aba ou copiar o link. Abrir o mesmo item novamente pode preparar outro evento; confira sua agenda antes de salvar.</p></details></section>`}
  function save(next){preferences.save(next);refresh();return next}
  function reminderSettings(){const r=prefs().reminders,root=openModal('Configurar lembretes',`<form id="reminder-settings-form"><div class="formerror" role="alert"></div>${check('reminders-enabled','Mostrar lembretes dentro do Retomar',r.enabled)}<div class="field"><label for="reminders-days">Antecedência por data</label><select id="reminders-days">${[[0,'Somente hoje'],[1,'Hoje e amanhã'],[3,'Próximos 3 dias'],[7,'Próximos 7 dias'],[14,'Próximos 14 dias'],[30,'Próximos 30 dias']].map(([v,l])=>option(v,l,r.aheadDays)).join('')}</select></div>${check('reminders-overdue','Incluir tarefas atrasadas',r.overdue)}<div class="field"><label for="reminders-snooze">Adiar um aviso por</label><select id="reminders-snooze">${[[15,'15 minutos'],[30,'30 minutos'],[60,'1 hora'],[180,'3 horas'],[1440,'24 horas']].map(([v,l])=>option(v,l,r.snoozeMinutes)).join('')}</select></div><p class="field-help">A data e o horário vêm antes da prioridade na ordem dos avisos. Um item sem horário fica atrasado após o fim da sua data. Dispensar hoje oculta apenas o aviso; a tarefa permanece no planejamento. Alertas com o Retomar fechado dependem dos avisos do Google Agenda.</p><button class="textbtn" type="button" id="clear-reminder-dismissals">Limpar adiamentos e avisos dispensados</button><div class="dialogactions"><button class="btn secondary" type="button" id="cancel-planning-settings">Cancelar</button><button class="btn primary" type="submit">Salvar lembretes</button></div><p class="field-help save-note">Preferências salvas neste aparelho.</p></form>`);
    let clear=false;root.querySelector('#clear-reminder-dismissals').onclick=e=>{clear=true;e.target.textContent='Avisos serão reativados ao salvar.';root.querySelector('#reminders-enabled').dispatchEvent(new Event('change',{bubbles:true}))};root.querySelector('#cancel-planning-settings').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{try{if(!checkForm(e.target))return;const next=structuredClone(prefs());next.reminders={enabled:root.querySelector('#reminders-enabled').checked,aheadDays:Number(root.querySelector('#reminders-days').value),overdue:root.querySelector('#reminders-overdue').checked,snoozeMinutes:Number(root.querySelector('#reminders-snooze').value)};if(clear)next.dismissals={};save(next);closeModal(true);toast('Lembretes configurados neste aparelho.');onOpen?.(false)}catch(error){const errorNode=root.querySelector('.formerror');errorNode.textContent=error.message;errorNode.scrollIntoView({block:'nearest'})}});
  }
  function calendarSettings(){
    const c=prefs().calendar,root=openModal('Ajustar Google Agenda',`<form id="calendar-settings-form"><div class="formerror" role="alert"></div><p class="calendar-simple-note">Toque no calendário da tarefa e confirme em <strong>Salvar</strong> no Google Agenda.</p>
      <div class="fieldsrow"><div class="field"><label for="calendar-duration">Duração dos eventos com horário</label><select data-full-value id="calendar-duration">${[15,30,45,60,90,120,180].map(v=>option(v,v+' minutos',c.duration)).join('')}</select></div><div class="field"><label for="calendar-no-time">Quando o item não tem horário</label><select data-full-value id="calendar-no-time">${option('allDay','Evento de dia inteiro',c.undatedTime)}${option('defaultTime','Usar horário padrão',c.undatedTime)}</select></div></div>
      <div class="field"><label for="calendar-default-time">Horário padrão</label><input type="time" id="calendar-default-time" step="60" value="${esc(c.defaultTime)}"></div>
      ${check('calendar-notes','Incluir as observações no evento',c.includeNotes)}${check('calendar-priority-title','Incluir a prioridade no título do evento',c.priorityTitle)}
      <details class="settings-details"><summary>Notificações no Google Agenda</summary>${notificationGuide()}</details>
      <details class="settings-details" id="calendar-timezone"><summary>Fuso horário</summary><div class="field"><label for="calendar-zone">Fuso dos prazos e eventos</label><input id="calendar-zone" required maxlength="100" autocomplete="off" spellcheck="false" value="${esc(c.timeZone)}" placeholder="America/Sao_Paulo"><small class="field-help">Também define os dias dos lembretes. Exemplos: America/Sao_Paulo, America/Manaus, Europe/Lisbon ou UTC.</small></div></details>
      <div class="dialogactions"><button class="btn secondary" type="button" id="cancel-planning-settings">Cancelar</button><button class="btn primary" type="submit">Salvar opções</button></div><p class="field-help save-note">Preferências salvas neste aparelho.</p></form>`);
    const defaultTime=root.querySelector('#calendar-default-time'),noTime=root.querySelector('#calendar-no-time'),zone=root.querySelector('#calendar-zone');
    const update=()=>{defaultTime.disabled=noTime.value!=='defaultTime';defaultTime.required=!defaultTime.disabled};noTime.onchange=update;update();
    root.querySelector('#cancel-planning-settings').onclick=()=>closeModal();
    root.querySelector('form').onsubmit=submitOnce(async e=>{try{
      zone.setCustomValidity('');if(!validZone(zone.value.trim()))zone.setCustomValidity('Informe um fuso válido, por exemplo America/Sao_Paulo.');if(!checkForm(e.target))return;
      const next=structuredClone(prefs());next.calendar={duration:Number(root.querySelector('#calendar-duration').value),undatedTime:noTime.value,defaultTime:defaultTime.value||c.defaultTime,timeZone:zone.value.trim(),includeNotes:root.querySelector('#calendar-notes').checked,priorityTitle:root.querySelector('#calendar-priority-title').checked};
      save(next);closeModal(true);toast('Opções salvas. Confira a notificação e confirme em Salvar no Google Agenda.');onOpen?.(false);
    }catch(error){const errorNode=root.querySelector('.formerror');errorNode.textContent=error.message;errorNode.scrollIntoView({block:'nearest'})}});
  }
  function webHelp(id){
    const state=getState(),t=state.items[id];if(!t||t.deleted)throw Error('Este item não está disponível.');
    if(!t.date){onEdit(id);return}
    const url=calendarTemplate(state,id,prefs().calendar,appUrl);
    const root=openModal('Adicionar ao Google Agenda',`<p class="confirmtext"><strong>${esc(t.title)}</strong></p><p>Abra o evento, entre na sua conta Google se solicitado e toque em <strong>Salvar</strong>. Você não precisa configurar uma conexão no Retomar.</p><div class="calendar-open-actions"><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('calendar-plus')} Abrir Google Agenda</a><a class="btn secondary" href="${esc(url)}">Abrir nesta aba</a><button class="btn secondary" type="button" id="calendar-copy-link">Copiar link do evento</button></div><p class="field-help">Se aparecer uma página de apresentação, entre na sua conta Google e abra o link novamente. No celular, também pode abrir este link no Chrome ou Safari. A cor é escolhida no Google. Abrir novamente pode preparar outro evento; confira sua agenda antes de salvar.</p><details class="settings-details" open><summary>Escolher uma notificação</summary>${notificationGuide()}</details><p id="calendar-copy-status" class="field-help" role="status"></p><div class="field" id="calendar-manual-copy" hidden><label for="calendar-event-link">Link do evento para copiar</label><textarea id="calendar-event-link" readonly rows="4" spellcheck="false">${esc(url)}</textarea></div>`);
    root.querySelector('#calendar-copy-link').onclick=async()=>{try{
      if(!target.navigator?.clipboard?.writeText)throw Error();await target.navigator.clipboard.writeText(url);
      root.querySelector('#calendar-copy-status').textContent='Link copiado. Cole no navegador para abrir o evento e salvar.';
    }catch{root.querySelector('#calendar-manual-copy').hidden=false;const field=root.querySelector('#calendar-event-link');field.focus();field.select();root.querySelector('#calendar-copy-status').textContent='Selecione e copie o link abaixo para abrir no navegador.'}};
  }
  function send(id){const t=getState().items[id];if(!t||t.deleted){toast('Este item não está disponível.');return}if(!t.date){toast('Defina uma data e salve o item antes de enviar ao Google Agenda.');onEdit(id);return}webHelp(id)}
  function refresh(){const bell=target.document.querySelector('.reminder-trigger');if(bell){const count=items().length;bell.setAttribute('aria-label','Lembretes: '+count+' '+(count===1?'prazo próximo ou atrasado':'prazos próximos ou atrasados'));let badge=bell.querySelector('.reminder-count');if(count){if(!badge){badge=target.document.createElement('span');badge.className='reminder-count';badge.setAttribute('aria-hidden','true');bell.append(badge)}badge.textContent=count>99?'99+':String(count)}else badge?.remove()}const summary=target.document.querySelector('#planning-summary');if(summary){const content=summaryContent();if(summary.innerHTML!==content)summary.innerHTML=content;}const result=target.document.querySelector('#reminders-results');if(result&&!target.document.activeElement?.closest('#reminders-results'))result.innerHTML=reminderRows();}
  function reload(){preferences.reload();refresh()}

  const storageChanged=e=>{if(e.key===PLANNING_KEY){reload();if(!target.document.querySelector('dialog[open]'))onOpen?.(false)}};
  async function action(name,data){try{if(name==='planning-open'){visible=60;onOpen(true)}else if(name==='planning-reminder-settings')reminderSettings();else if(name==='planning-calendar-settings')calendarSettings();else if(name==='planning-calendar-notifications')notificationHelp();else if(name==='planning-calendar-web')toast('No Google Agenda, confira a notificação e confirme em Salvar para adicionar o evento.',{label:'Não abriu?',run:()=>{try{webHelp(data.id)}catch(error){toast(error.message)}}});else if(name==='planning-calendar')send(data.id);else if(name==='planning-edit')onEdit(data.id);else if(name==='planning-complete')await onComplete(data.id);else if(name==='planning-snooze'||name==='planning-dismiss'){const t=getState().items[data.id];if(!t||t.deleted||!openItem(t))return;const before=structuredClone(prefs());save(postpone(prefs(),t,now(),name==='planning-dismiss'));const result=target.document.querySelector('#reminders-results');if(result)result.innerHTML=reminderRows();toast(name==='planning-dismiss'?'Aviso dispensado por hoje. A tarefa permanece no planejamento.':'Aviso adiado neste aparelho.',{label:'Desfazer',run:()=>{try{const next=structuredClone(prefs());if(before.dismissals[data.id])next.dismissals[data.id]=before.dismissals[data.id];else delete next.dismissals[data.id];save(next);if(result?.isConnected)result.innerHTML=reminderRows()}catch(e){toast(e.message)}}})}else if(name==='planning-more'){visible+=60;const result=target.document.querySelector('#reminders-results');if(result)result.innerHTML=reminderRows()}}catch(error){toast(error.message)}
  }
  return {header,summary,page,settings,calendarButton,action,refresh,reload,start(){target.addEventListener('storage',storageChanged);timer=target.setInterval(()=>{if(!target.document.hidden&&!target.document.querySelector('dialog[open]')&&!target.document.documentElement.classList.contains('drag-active')&&!target.document.activeElement?.matches('input,textarea,select'))refresh()},30000)},dispose(){target.clearInterval(timer);target.removeEventListener('storage',storageChanged)}};
}
